/**
 * Convert an infix expression to postfix (Reverse Polish) notation.
 *
 * Supports: +, -, *, /, ^, parentheses, and multi-character
 * integer/decimal operands separated by spaces.
 *
 * Uses the Shunting Yard algorithm (Dijkstra).
 *
 * @param {string} expr - Infix expression (tokens separated by spaces)
 * @returns {string}    - Postfix expression
 */
function validate_schema(expr) {
  if (typeof expr !== 'string') {
    throw new TypeError('Expression must be a string');
  }

  const precedence = { '+': 1, '-': 1, '*': 2, '/': 2, '^': 3 };
  const rightAssoc = new Set(['^']);

  const output = [];
  const ops = [];

  const tokens = expr.trim().split(/\s+/);

  for (const token of tokens) {
    if (token === '') continue;

    if (token === '(') {
      ops.push(token);
    } else if (token === ')') {
      while (ops.length > 0 && ops[ops.length - 1] !== '(') {
        output.push(ops.pop());
      }
      if (ops.length === 0) {
        throw new SyntaxError('Mismatched parentheses: unmatched ")"');
      }
      ops.pop(); // discard '('
    } else if (precedence[token] !== undefined) {
      while (
        ops.length > 0 &&
        ops[ops.length - 1] !== '(' &&
        precedence[ops[ops.length - 1]] !== undefined &&
        (precedence[ops[ops.length - 1]] > precedence[token] ||
          (precedence[ops[ops.length - 1]] === precedence[token] &&
            !rightAssoc.has(token)))
      ) {
        output.push(ops.pop());
      }
      ops.push(token);
    } else {
      // Operand (number or variable name)
      output.push(token);
    }
  }

  while (ops.length > 0) {
    const op = ops.pop();
    if (op === '(') {
      throw new SyntaxError('Mismatched parentheses: unmatched "("');
    }
    output.push(op);
  }

  return output.join(' ');
}

module.exports = { validate_schema };

// ---------------------------------------------------------------------------
// Test cases
// ---------------------------------------------------------------------------

function runTests() {
  let passed = 0;
  let failed = 0;

  function assert(actual, expected, desc) {
    if (actual === expected) {
      passed++;
      console.log(`  PASS: ${desc}`);
    } else {
      failed++;
      console.error(`  FAIL: ${desc}`);
      console.error(`        expected: "${expected}"`);
      console.error(`        actual:   "${actual}"`);
    }
  }

  function assertThrows(fn, desc) {
    try {
      fn();
      failed++;
      console.error(`  FAIL: ${desc} (did not throw)`);
    } catch {
      passed++;
      console.log(`  PASS: ${desc}`);
    }
  }

  // ── Basic arithmetic ─────────────────────────────────────────────────────

  console.log('\n=== Basic arithmetic ===');
  assert(validate_schema('3 + 4'), '3 4 +', 'simple addition');
  assert(validate_schema('10 - 5'), '10 5 -', 'simple subtraction');
  assert(validate_schema('6 * 7'), '6 7 *', 'simple multiplication');
  assert(validate_schema('8 / 2'), '8 2 /', 'simple division');
  assert(validate_schema('2 ^ 3'), '2 3 ^', 'simple exponentiation');

  // ── Operator precedence ──────────────────────────────────────────────────

  console.log('\n=== Operator precedence ===');
  assert(validate_schema('3 + 4 * 5'), '3 4 5 * +', '* binds tighter than +');
  assert(validate_schema('3 * 4 + 5'), '3 4 * 5 +', '* evaluated before +');
  assert(validate_schema('1 + 2 * 3 - 4'), '1 2 3 * + 4 -', 'mixed + * -');
  assert(validate_schema('2 + 3 * 4 ^ 2'), '2 3 4 2 ^ * +', '^ > * > +');
  assert(validate_schema('2 ^ 3 * 4'), '2 3 ^ 4 *', '^ before *');

  // ── Left-associativity ───────────────────────────────────────────────────

  console.log('\n=== Left-associativity ===');
  assert(validate_schema('8 / 4 / 2'), '8 4 / 2 /', '/ is left-assoc');
  assert(validate_schema('10 - 3 - 2'), '10 3 - 2 -', '- is left-assoc');
  assert(validate_schema('2 ^ 3 ^ 4'), '2 3 4 ^ ^', '^ is right-assoc');

  // ── Parentheses ──────────────────────────────────────────────────────────

  console.log('\n=== Parentheses ===');
  assert(validate_schema('( 3 + 4 ) * 5'), '3 4 + 5 *', 'parens override precedence');
  assert(validate_schema('3 * ( 4 + 5 )'), '3 4 5 + *', 'parens after *');
  assert(validate_schema('( 1 + 2 ) * ( 3 + 4 )'), '1 2 + 3 4 + *', 'two paren groups');
  assert(validate_schema('( ( 1 + 2 ) * 3 )'), '1 2 + 3 *', 'nested parens');
  assert(validate_schema('( ( ( 1 ) ) )'), '1', 'deeply nested parens');

  // ── Single operand ───────────────────────────────────────────────────────

  console.log('\n=== Single operand ===');
  assert(validate_schema('42'), '42', 'single number');
  assert(validate_schema('x'), 'x', 'single variable');

  // ── Variable names ───────────────────────────────────────────────────────

  console.log('\n=== Variable names ===');
  assert(validate_schema('a + b'), 'a b +', 'simple variables');
  assert(validate_schema('x * y + z'), 'x y * z +', 'variables with precedence');
  assert(validate_schema('( a + b ) * c'), 'a b + c *', 'variables with parens');

  // ── Complex expressions ──────────────────────────────────────────────────

  console.log('\n=== Complex expressions ===');
  assert(
    validate_schema('3 + 4 * 2 / ( 1 - 5 ) ^ 2 ^ 3'),
    '3 4 2 * 1 5 - 2 3 ^ ^ / +',
    'full complex expression'
  );
  assert(
    validate_schema('( a + b ) * ( c - d ) / e'),
    'a b + c d - * e /',
    'complex with variables'
  );
  assert(
    validate_schema('a + b * c ^ d - e'),
    'a b c d ^ * + e -',
    'mixed operators no parens'
  );

  // ── Whitespace handling ──────────────────────────────────────────────────

  console.log('\n=== Whitespace handling ===');
  assert(validate_schema('  3   +  4  '), '3 4 +', 'extra whitespace');
  assert(validate_schema('3+4'), '3+4', 'no spaces (treated as single token)');
  assert(validate_schema('\t3 + 4\n'), '3 4 +', 'tabs and newlines');

  // ── Error cases ──────────────────────────────────────────────────────────

  console.log('\n=== Error cases ===');
  assertThrows(() => validate_schema('( 3 + 4'), 'unmatched "(" throws');
  assertThrows(() => validate_schema('3 + 4 )'), 'unmatched ")" throws');
  assertThrows(() => validate_schema('( ( 3 + 4 )'), 'nested unmatched "(" throws');
  assertThrows(() => validate_schema(123), 'non-string input throws');
  assertThrows(() => validate_schema(null), 'null input throws');

  // ── Same-precedence chains ───────────────────────────────────────────────

  console.log('\n=== Same-precedence chains ===');
  assert(validate_schema('1 + 2 + 3 + 4'), '1 2 + 3 + 4 +', 'chain of +');
  assert(validate_schema('1 * 2 * 3 * 4'), '1 2 * 3 * 4 *', 'chain of *');
  assert(validate_schema('2 ^ 3 ^ 4 ^ 5'), '2 3 4 5 ^ ^ ^', 'chain of ^ (right-assoc)');

  // ── Adjacent operators ───────────────────────────────────────────────────

  console.log('\n=== Edge-case: adjacent same tokens ===');
  assert(validate_schema('( a )'), 'a', 'redundant parens');
  assert(validate_schema('( ( a + b ) )'), 'a b +', 'double-wrapped parens');

  // ── Summary ──────────────────────────────────────────────────────────────

  console.log(`\n${'='.repeat(50)}`);
  console.log(`Results: ${passed} passed, ${failed} failed, ${passed + failed} total`);
  if (failed > 0) process.exit(1);
}

runTests();
